//! Funded Stellar starter — generate a keypair and fund it via Friendbot.
//!
//! Generated by `stellar-qk init --template funded`.
//!
//! ## Run
//!
//! ```
//! cargo run
//! ```
//!
//! The program will:
//!   1. Generate a fresh keypair
//!   2. Fund the new account on Testnet via Friendbot
//!   3. Fetch and print the opening XLM balance from Horizon

use anyhow::Result;
use stellar_qk::{
    keys::generate_keypair,
    network::{Network, friendbot_fund},
    horizon::fetch_balances,
};

#[tokio::main]
async fn main() -> Result<()> {
    println!("=== Stellar funded starter (Testnet) ===\n");

    // 1. Generate a fresh keypair
    let kp = generate_keypair();
    println!("Public key  : {}", kp.public_key);
    println!("Secret seed : {}", kp.secret_seed);
    println!();
    println!("⚠  Never share or commit your secret seed.\n");

    // 2. Fund via Friendbot
    println!("Funding account on Testnet via Friendbot…");
    match friendbot_fund(&kp.public_key, Network::Testnet).await {
        Ok(tx_hash) => println!("✓ Funded!  tx hash: {tx_hash}"),
        Err(e)      => {
            eprintln!("✗ Friendbot error: {e}");
            eprintln!("  (Are you offline? Testnet might be down.)");
            return Ok(());
        }
    }

    // 3. Fetch balance
    println!("\nFetching balance from Horizon…");
    let balances = fetch_balances(&kp.public_key, Network::Testnet).await?;

    if balances.is_empty() {
        println!("No balances found yet — Horizon may need a moment to index the account.");
    } else {
        println!("\n{:<20} {}", "Asset", "Balance");
        println!("{}", "-".repeat(35));
        for b in &balances {
            println!("{:<20} {}", b.asset, b.balance);
        }
    }

    println!("\nDone! Visit https://stellar.expert/explorer/testnet/account/{} to explore your account.",
             kp.public_key);

    Ok(())
}
